package dev.gemsmp;

import org.bukkit.*;
import org.bukkit.command.*;
import org.bukkit.entity.*;
import org.bukkit.event.*;
import org.bukkit.event.entity.*;
import org.bukkit.event.inventory.*;
import org.bukkit.event.player.*;
import org.bukkit.inventory.*;
import org.bukkit.inventory.meta.*;
import org.bukkit.persistence.*;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.util.Vector;
import java.util.*;

/** GemSMP single-plugin foundation. */
public final class GemSMP extends JavaPlugin implements Listener {
 enum Gem { LUCK, SWIFT, EMBER, TIDE, AIR, PRISM, LUNAR, CHRONOS, SOUL }
 private NamespacedKey kind, awakened, bind, hearts, uses, kills, passiveKey;
 private final Map<UUID,Gem> owners=new HashMap<>(); private final Map<UUID,Integer> mastery=new HashMap<>();
 private final Map<UUID,Boolean> passiveOn=new HashMap<>(); private final Map<String,Long> cd=new HashMap<>();
 private final Map<UUID,Set<UUID>> trusted=new HashMap<>(); private final Map<UUID,Integer> killCount=new HashMap<>(), abilityCount=new HashMap<>(), heartCount=new HashMap<>();
 private final Map<UUID,Deque<Location>> history=new HashMap<>();
 @Override public void onEnable(){saveDefaultConfig();kind=new NamespacedKey(this,"gem");awakened=new NamespacedKey(this,"awakened");bind=new NamespacedKey(this,"bound");hearts=new NamespacedKey(this,"hearts");uses=new NamespacedKey(this,"uses");kills=new NamespacedKey(this,"kills");passiveKey=new NamespacedKey(this,"passive");getServer().getPluginManager().registerEvents(this,this);getServer().getScheduler().runTaskTimer(this,()->{for(Player p:Bukkit.getOnlinePlayers()){Deque<Location>d=history.computeIfAbsent(p.getUniqueId(),x->new ArrayDeque<>());d.addLast(p.getLocation().clone());while(d.size()>30)d.removeFirst();applyPassive(p);}},1,1);}
 @Override public void onDisable(){ }
 private ItemStack item(String type){Material m= switch(type){case "heart"->Material.PLAYER_HEAD;case "curse"->Material.BLACKSTONE;case "upgrader"->Material.EMERALD;default->Material.AMETHYST_SHARD;};ItemStack i=new ItemStack(m);ItemMeta meta=i.getItemMeta();PersistentDataContainer p=meta.getPersistentDataContainer();p.set(kind,PersistentDataType.STRING,type);if(type.startsWith("gem:")){p.set(kind,PersistentDataType.STRING,type.substring(4));p.set(awakened,PersistentDataType.BYTE,(byte)0);}meta.setDisplayName(ChatColor.LIGHT_PURPLE+type.replace(':',' ').toUpperCase());meta.setLore(List.of(ChatColor.GRAY+"GemSMP artifact",ChatColor.DARK_PURPLE+"Unique item"));i.setItemMeta(meta);return i;}
 private String itemKind(ItemStack i){if(i==null||!i.hasItemMeta())return null;return i.getItemMeta().getPersistentDataContainer().get(kind,PersistentDataType.STRING);}
 private boolean gemItem(ItemStack i){return itemKind(i)!=null&&Arrays.stream(Gem.values()).anyMatch(g->g.name().equals(itemKind(i)));}
 private Gem gem(ItemStack i){try{return Gem.valueOf(itemKind(i));}catch(Exception e){return null;}}
 private Player activeHolder(Gem g){for(var e:owners.entrySet())if(e.getValue()==g){Player p=Bukkit.getPlayer(e.getKey());if(p!=null)return p;}return null;}
 private boolean holding(Player p){return gem(p.getInventory().getItemInMainHand())==owners.get(p.getUniqueId())||gem(p.getInventory().getItemInOffHand())==owners.get(p.getUniqueId());}
 private boolean ready(Player p,int slot,int seconds){String key=p.getUniqueId()+":"+slot;long now=System.currentTimeMillis(),end=cd.getOrDefault(key,0L);if(now<end){p.sendMessage(ChatColor.RED+"Cooldown: "+((end-now+999)/1000)+"s");return false;}cd.put(key,now+seconds*1000L);return true;}
 private void applyPassive(Player p){Gem g=owners.get(p.getUniqueId());if(g==null||!passiveOn.getOrDefault(p.getUniqueId(),true)||!holding(p))return;switch(g){case LUCK->{p.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.LUCK,40,0,true,false));p.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.HERO_OF_THE_VILLAGE,40,0,true,false));}case SWIFT->{p.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.SPEED,40,0,true,false));p.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.HASTE,40,0,true,false));}case EMBER->{p.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.FIRE_RESISTANCE,40,0,true,false));if(p.getFireTicks()>0)p.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.REGENERATION,40,1,true,false));}case TIDE->{if(p.isInWater()){p.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.SPEED,40,0,true,false));p.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.WATER_BREATHING,40,0,true,false));}}case LUNAR->{if(p.getWorld().getEnvironment()==World.Environment.THE_END||p.getWorld().getEnvironment()==World.Environment.NORMAL&&p.getWorld().getTime()>13000&&p.getWorld().getTime()<23000)p.setMaxHealth(Math.min(24,p.getMaxHealth()));}default->{}}}
 private boolean mastered(Player p,int level){return mastery.getOrDefault(p.getUniqueId(),0)>=level;}
 private void activate(Player p,int n){Gem g=owners.get(p.getUniqueId());if(g==null||!holding(p)){p.sendMessage(ChatColor.RED+"Hold your awakened gem.");return;}if(!mastered(p,n)){p.sendMessage(ChatColor.RED+"You haven't unlocked this ability yet.");return;}int[] c={0,25,35,150};int sec=c[n];if(!ready(p,n,sec))return;abilityCount.merge(p.getUniqueId(),1,Integer::sum);p.getWorld().playSound(p.getLocation(),Sound.ENTITY_PLAYER_LEVELUP,1,1.4f);switch(g){case LUCK->{if(n==1){if(Math.random()<.75){p.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.SPEED,140,1));p.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.REGENERATION,140,1));p.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.RESISTANCE,140,1));}else{p.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.WEAKNESS,80,0));p.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.SLOWNESS,80,2));}}else luckSwap(p);}case SWIFT->{if(n==1){p.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.SPEED,160,1));pushNearby(p,3,1);}else dash(p);}case EMBER->{if(n==1)fireball(p);else blast(p,4,2.5);}case TIDE->{if(n==1)pushNearby(p,5,2);else blast(p,3.5,4);}case AIR->{if(n==1)pushNearby(p,5,3);else p.setVelocity(p.getVelocity().add(new Vector(0,1.5,0)));}case PRISM->{if(n==1)rayDamage(p,8,2);else rayDamage(p,12,1);}case LUNAR->{if(n==1)p.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.REGENERATION,1200,1));else p.getWorld().setTime(18000);}case CHRONOS->{if(n==1)rewind(p,3);else rewindTarget(p,6);}case SOUL->{if(n==1)soulbound(p);else soulBlast(p);} }}
 private void luckSwap(Player p){LivingEntity t=target(p,12);if(t==null){p.sendMessage(ChatColor.RED+"No target.");return;}PotionEffectType[] pool={PotionEffectType.SPEED,PotionEffectType.REGENERATION,PotionEffectType.WEAKNESS,PotionEffectType.SLOWNESS,PotionEffectType.POISON,PotionEffectType.RESISTANCE};p.addPotionEffect(new org.bukkit.potion.PotionEffect(pool[new Random().nextInt(2)],200,0));if(t instanceof Player q&&!isTrusted(p,q))q.addPotionEffect(new org.bukkit.potion.PotionEffect(pool[new Random().nextInt(pool.length)],200,0));}
 private LivingEntity target(Player p,int range){for(Entity e:p.getNearbyEntities(range,range,range))if(e instanceof LivingEntity l&&l!=p&&e.getLocation().distance(p.getLocation())<range)return l;return null;}
 private boolean isTrusted(Player a,Player b){return trusted.getOrDefault(a.getUniqueId(),Set.of()).contains(b.getUniqueId());}
 private void pushNearby(Player p,double range,double strength){for(Entity e:p.getNearbyEntities(range,range,range))if(e instanceof Player q&&q!=p&&!isTrusted(p,q))q.setVelocity(q.getLocation().toVector().subtract(p.getLocation().toVector()).normalize().multiply(strength));}
 private void dash(Player p){p.setVelocity(p.getLocation().getDirection().multiply(1.7).setY(.35));new BukkitRunnable(){int i=0;public void run(){if(i++>6){cancel();return;}for(Entity e:p.getNearbyEntities(1.3,1.3,1.3))if(e instanceof Player q&&q!=p&&!isTrusted(p,q)){q.damage(2,p);q.setVelocity(p.getLocation().getDirection().multiply(1.1));}}}.runTaskTimer(this,0,1);}
 private void fireball(Player p){p.launchProjectile(org.bukkit.entity.Fireball.class).setYield(0);}
 private void blast(Player p,double damage,double radius){for(Entity e:p.getNearbyEntities(radius,radius,radius))if(e instanceof Player q&&q!=p&&!isTrusted(p,q)){q.damage(damage,p);q.setVelocity(q.getLocation().toVector().subtract(p.getLocation().toVector()).normalize().multiply(1.3));}p.getWorld().spawnParticle(Particle.FLAME,p.getLocation(),80,radius/2,radius/2,radius/2);}
 private void rayDamage(Player p,int distance,double damage){Vector d=p.getLocation().getDirection();for(int i=1;i<=distance;i++){Location l=p.getLocation().add(d.clone().multiply(1));p.getWorld().spawnParticle(Particle.END_ROD,l,3);for(Entity e : l.getWorld().getNearbyEntities(l,.6,.6,.6))if(e instanceof Player q&&q!=p&&!isTrusted(p,q))q.damage(damage,p);}}
 private void rewind(Player p,int sec){Deque<Location>d=history.get(p.getUniqueId());if(d==null||d.size()<sec+1)return;Location l=d.toArray(new Location[0])[Math.max(0,d.size()-sec-1)];p.teleport(l);}
 private void rewindTarget(Player p,int sec){LivingEntity t=target(p,12);if(t instanceof Player q){Deque<Location>d=history.get(q.getUniqueId());if(d!=null&&d.size()>=sec+1)q.teleport(d.toArray(new Location[0])[Math.max(0,d.size()-sec-1)]);}}
 private void soulbound(Player p){LivingEntity t=target(p,10);if(t instanceof Player q&&!isTrusted(p,q)){q.damage(4,p);p.setHealth(Math.min(p.getMaxHealth(),p.getHealth()+4));}}
 private void soulBlast(Player p){p.launchProjectile(org.bukkit.entity.Snowball.class);}
 @EventHandler public void onInteract(PlayerInteractEvent e){if(!e.getAction().isRightClick())return;Player p=e.getPlayer();String k=itemKind(e.getItem());if(k==null)return;e.setCancelled(true);if(k.equals("curse")){Gem g=owners.remove(p.getUniqueId());if(g!=null){p.getInventory().addItem(item("gem:"+g.name()));mastery.remove(p.getUniqueId());passiveOn.remove(p.getUniqueId());p.sendMessage(ChatColor.RED+"Your power was withdrawn.");}return;}if(k.equals("upgrader")){if(!owners.containsKey(p.getUniqueId()))return;int m=mastery.getOrDefault(p.getUniqueId(),0);mastery.put(p.getUniqueId(),Math.min(3,m+1));e.getItem().setAmount(e.getItem().getAmount()-1);p.sendMessage(ChatColor.GREEN+"Mastery upgraded to "+(m+1)+".");return;}if(k.equals("heart")){p.sendMessage(ChatColor.RED+"Corrupted Hearts are deposited through /deposit.");return;}try{Gem g=Gem.valueOf(k);if(owners.containsKey(p.getUniqueId())){p.sendMessage(ChatColor.RED+"You already have an awakened gem.");return;}if(activeHolder(g)!=null){p.sendMessage(ChatColor.RED+"This gem already has an owner.");return;}owners.put(p.getUniqueId(),g);mastery.put(p.getUniqueId(),0);passiveOn.put(p.getUniqueId(),true);e.getItem().setAmount(e.getItem().getAmount()-1);ItemStack bound=item(g.name());bound.getItemMeta().getPersistentDataContainer().set(bind,PersistentDataType.STRING,p.getUniqueId().toString());p.getInventory().setItemInOffHand(bound);p.sendMessage(ChatColor.GREEN+"GEM AWAKENED: "+g.name());p.sendTitle(ChatColor.GREEN+"GEM AWAKENED",ChatColor.GRAY+g.name(),10,50,20);}catch(Exception ignored){}}
 @EventHandler public void onDrop(PlayerDropItemEvent e){if(owners.containsKey(e.getPlayer().getUniqueId())){ItemStack i=e.getItemDrop().getItemStack();if(gem(i)||Objects.equals(itemKind(i),"curse"))e.setCancelled(true);}}
 @EventHandler public void onInv(InventoryClickEvent e){if(e.getWhoClicked() instanceof Player p&&owners.containsKey(p.getUniqueId())){if(gem(e.getCurrentItem())||gem(e.getCursor()))e.setCancelled(true);}}
 @EventHandler public void onDeath(PlayerDeathEvent e){Player p=e.getEntity();Gem g=owners.remove(p.getUniqueId());if(g!=null){ItemStack drop=item(g.name());drop.setAmount(1);drop.addUnsafeEnchantment(org.bukkit.enchantments.Enchantment.LUCK,1);e.getDrops().add(drop);mastery.remove(p.getUniqueId());p.getInventory().setItemInOffHand(null);String[] msg={"Fortune has abandoned its bearer.","Even the fastest eventually fall.","The last ember has gone cold.","The tides have lost their master.","The skies have lost their guardian.","The light of the Prism Gem has faded.","The eclipse has finally ended.","Time has stopped for its bearer.","The keeper of souls has fallen."};if(getConfig().getBoolean("gem-death-messages",true))e.setDeathMessage(ChatColor.DARK_PURPLE+msg[g.ordinal()]);}if(p.getKiller()!=null)killCount.merge(p.getKiller().getUniqueId(),1,Integer::sum);}
 @EventHandler public void onInvOpen(InventoryOpenEvent e){if(e.getPlayer() instanceof Player p&&owners.containsKey(p.getUniqueId())){}}
 @Override public boolean onCommand(CommandSender s,Command c,String label,String[] args){if(label.equalsIgnoreCase("startsmp")){if(!s.hasPermission("gemsmp.admin"))return true;List<Player> ps=new ArrayList<>(Bukkit.getOnlinePlayers());Collections.shuffle(ps);int n=0;for(Player p:ps){if(n>=9)break;Gem g=Gem.values()[n++];owners.put(p.getUniqueId(),g);mastery.put(p.getUniqueId(),0);passiveOn.put(p.getUniqueId(),true);p.getInventory().setItemInOffHand(item(g.name()));p.sendMessage(ChatColor.GREEN+"Your starting gem: "+g.name());}s.sendMessage(ChatColor.GREEN+"Assigned "+n+" unique gems.");return true;}if(label.equalsIgnoreCase("stopsmp")){if(!s.hasPermission("gemsmp.admin"))return true;owners.clear();mastery.clear();passiveOn.clear();cd.clear();for(Player p:Bukkit.getOnlinePlayers())p.getInventory().setItemInOffHand(null);s.sendMessage(ChatColor.RED+"Gem SMP state reset (inventory items must be manually cleared in this foundation build).");return true;}if(label.equalsIgnoreCase("activate1")){if(s instanceof Player p)activate(p,1);return true;}if(label.equalsIgnoreCase("activate2")){if(s instanceof Player p)activate(p,2);return true;}if(label.equalsIgnoreCase("activate3")){if(s instanceof Player p)activate(p,3);return true;}if(label.equalsIgnoreCase("passive")){if(s instanceof Player p&&args.length>0&&args[0].equalsIgnoreCase("toggle")){passiveOn.put(p.getUniqueId(),!passiveOn.getOrDefault(p.getUniqueId(),true));p.sendMessage(ChatColor.YELLOW+"Passive "+(passiveOn.get(p.getUniqueId())?"enabled":"disabled"));}return true;}if(label.equalsIgnoreCase("abilitytrust")){if(s instanceof Player p&&args.length>0){Player q=Bukkit.getPlayer(args[0]);if(q!=null)trusted.computeIfAbsent(p.getUniqueId(),x->new HashSet<>()).add(q.getUniqueId());p.sendMessage(ChatColor.GREEN+"Trusted ally.");}return true;}if(label.equalsIgnoreCase("gemstats")){if(s instanceof Player p){if(!getConfig().getBoolean("gemstats",true)){p.sendMessage(ChatColor.RED+"Stats are disabled.");return true;}p.sendMessage(ChatColor.GOLD+"Kills: "+killCount.getOrDefault(p.getUniqueId(),0)+" | Ability uses: "+abilityCount.getOrDefault(p.getUniqueId(),0)+" | Hearts: "+heartCount.getOrDefault(p.getUniqueId(),0));}return true;}if(label.equalsIgnoreCase("deposit")){if(s instanceof Player p)p.sendMessage(ChatColor.YELLOW+"Deposit GUI is not implemented in this build.");return true;}if(label.equalsIgnoreCase("eventstart")){s.sendMessage(ChatColor.YELLOW+"Event scheduler is not implemented in this build.");return true;}if(label.equalsIgnoreCase("title")){s.sendMessage(ChatColor.YELLOW+"Mastery title selection is not implemented in this build.");return true;}return false;}
}
